 import React, { useState, useEffect } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { getTeamEmoji } from '../services/footballApi'

export default function CommunityDetail() {
    const { id } = useParams()
    const { user, profile } = useAuth()
    const navigate = useNavigate()
    const [community, setCommunity] = useState(null)
    const [posts, setPosts] = useState([])
    const [isMember, setIsMember] = useState(false)
    const [isCreator, setIsCreator] = useState(false)
    const [loading, setLoading] = useState(true)
    const [showPaymentModal, setShowPaymentModal] = useState(false)
    const [newPost, setNewPost] = useState('')
    const [submitting, setSubmitting] = useState(false)

    useEffect(() => {
        loadCommunityData()
    }, [id, user])

    const loadCommunityData = async () => {
        setLoading(true)
        try {
            // Load community details
            const { data: communityData } = await supabase
                .from('communities')
                .select(`
                    *,
                    profiles:creator_id (id, username, full_name, avatar_url)
                `)
                .eq('id', id)
                .single()

            setCommunity(communityData)
            setIsCreator(user?.id === communityData?.creator_id)

            // Check if user is a member
            if (user) {
                const { data: memberData } = await supabase
                    .from('community_members')
                    .select('*')
                    .eq('community_id', id)
                    .eq('user_id', user.id)
                    .eq('status', 'active')
                    .single()

                setIsMember(!!memberData)
            }

            // Load posts
            const { data: postsData } = await supabase
                .from('community_posts')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url)
                `)
                .eq('community_id', id)
                .order('created_at', { ascending: false })

            setPosts(postsData || [])

            // Load members count
            const { count } = await supabase
                .from('community_members')
                .select('*', { count: 'exact', head: true })
                .eq('community_id', id)
                .eq('status', 'active')

            if (communityData) {
                setCommunity({ ...communityData, member_count: count || 0 })
            }

        } catch (error) {
            console.error('Error loading community:', error)
        } finally {
            setLoading(false)
        }
    }

    const handleJoin = () => {
        if (!user) {
            alert('Please sign in to join this community')
            navigate('/login')
            return
        }
        setShowPaymentModal(true)
    }

    const handlePayment = async () => {
        setSubmitting(true)
        try {
            // Check if user has a profile
            const { data: profileData } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', user.id)
                .single()

            if (!profileData) {
                await supabase
                    .from('profiles')
                    .insert({
                        id: user.id,
                        username: user.email?.split('@')[0] || 'user',
                        full_name: user.email?.split('@')[0] || 'user'
                    })
            }

            // Record payment with 50/50 split
            const { error: paymentError } = await supabase
                .from('subscription_payments')
                .insert({
                    community_id: id,
                    user_id: user.id,
                    amount: 50.00,
                    currency: 'ZAR',
                    platform_fee: 25.00,
                    creator_earnings: 25.00,
                    status: 'success'
                })

            if (paymentError) throw paymentError

            // Add user as member
            const { error: memberError } = await supabase
                .from('community_members')
                .insert({
                    community_id: id,
                    user_id: user.id,
                    status: 'active',
                    expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
                })

            if (memberError) throw memberError

            // Update member count
            const { data: communityData } = await supabase
                .from('communities')
                .select('member_count')
                .eq('id', id)
                .single()

            await supabase
                .from('communities')
                .update({ 
                    member_count: (communityData?.member_count || 0) + 1
                })
                .eq('id', id)

            setShowPaymentModal(false)
            setIsMember(true)
            alert('🎉 Welcome to the community!')
            loadCommunityData()

        } catch (error) {
            console.error('Error joining community:', error)
            alert('Failed to join community. Please try again.')
        } finally {
            setSubmitting(false)
        }
    }

    const handleCreatePost = async (e) => {
        e.preventDefault()
        
        if (!newPost.trim()) {
            alert('Please write something')
            return
        }
        
        // Only creator can post
        if (!isCreator) {
            alert('Only the community creator can post in this community')
            return
        }

        setSubmitting(true)
        try {
            console.log('Creating post with:', {
                community_id: id,
                user_id: user.id,
                text: newPost.trim()
            })

            const { data, error } = await supabase
                .from('community_posts')
                .insert({
                    community_id: id,
                    user_id: user.id,
                    text: newPost.trim()
                })
                .select()
                .single()

            if (error) {
                console.error('Supabase error:', error)
                throw error
            }

            console.log('Post created:', data)

            // Update post count
            const { data: communityData } = await supabase
                .from('communities')
                .select('post_count')
                .eq('id', id)
                .single()

            await supabase
                .from('communities')
                .update({ 
                    post_count: (communityData?.post_count || 0) + 1
                })
                .eq('id', id)

            setNewPost('')
            await loadCommunityData()
            alert('✅ Post created successfully!')
            
        } catch (error) {
            console.error('Error creating post:', error)
            alert('Failed to create post: ' + error.message)
        } finally {
            setSubmitting(false)
        }
    }

    const handleLike = async (postId) => {
        if (!user) {
            alert('Please sign in to like posts')
            return
        }

        try {
            // Check if already liked
            const { data: existing } = await supabase
                .from('community_post_likes')
                .select('*')
                .eq('post_id', postId)
                .eq('user_id', user.id)
                .single()

            // Get current likes count
            const { data: postData } = await supabase
                .from('community_posts')
                .select('likes_count')
                .eq('id', postId)
                .single()

            const currentLikes = postData?.likes_count || 0

            if (existing) {
                // Unlike
                await supabase
                    .from('community_post_likes')
                    .delete()
                    .eq('post_id', postId)
                    .eq('user_id', user.id)

                await supabase
                    .from('community_posts')
                    .update({ 
                        likes_count: Math.max(0, currentLikes - 1) 
                    })
                    .eq('id', postId)
            } else {
                // Like
                await supabase
                    .from('community_post_likes')
                    .insert({ 
                        post_id: postId, 
                        user_id: user.id 
                    })

                await supabase
                    .from('community_posts')
                    .update({ 
                        likes_count: currentLikes + 1 
                    })
                    .eq('id', postId)
            }

            // Refresh posts
            loadCommunityData()
        } catch (error) {
            console.error('Error liking post:', error)
            alert('Failed to like post. Please try again.')
        }
    }

    // Check if user can post (ONLY creator)
    const canPost = isCreator

    if (loading) {
        return (
            <div className="text-center py-12">
                <div className="text-gray-500">Loading...</div>
            </div>
        )
    }

    if (!community) {
        return (
            <div className="text-center py-12 bg-white rounded-xl shadow-md">
                <div className="text-4xl mb-4">🔍</div>
                <p className="text-gray-500">Community not found</p>
                <Link to="/community" className="text-green-600 hover:underline mt-4 block">
                    ← Back to Communities
                </Link>
            </div>
        )
    }

    return (
        <div>
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-start justify-between">
                    <div>
                        <div className="flex items-center gap-2">
                            <span className="text-3xl">🏛️</span>
                            <h1 className="text-2xl font-bold text-gray-800">{community.name}</h1>
                            {isCreator && (
                                <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>
                            )}
                        </div>
                        <p className="text-gray-500 mt-1">{community.description || 'A private community for football predictions'}</p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span>👥 {community.member_count || 0} members</span>
                            <span>📝 {community.post_count || 0} posts</span>
                            <span>💰 R50/month</span>
                        </div>
                        {isCreator && (
                            <div className="mt-2 text-sm text-green-600">
                                💰 You earn R25 per member (50% of R50)
                            </div>
                        )}
                        {isCreator && (
                            <div className="mt-1 text-xs text-gray-500">
                                👑 You are the community admin. Only you can post announcements.
                            </div>
                        )}
                    </div>
                    <div>
                        {isCreator ? (
                            <span className="text-sm bg-yellow-100 text-yellow-800 px-4 py-2 rounded-lg">Creator</span>
                        ) : isMember ? (
                            <span className="text-sm bg-green-100 text-green-800 px-4 py-2 rounded-lg">✓ Member</span>
                        ) : (
                            <button 
                                onClick={handleJoin}
                                className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium"
                            >
                                Join R50/month
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {canPost ? (
                <>
                    {/* Create Post - Only for Creator */}
                    <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                        <form onSubmit={handleCreatePost} className="flex gap-3">
                            <input
                                type="text"
                                value={newPost}
                                onChange={(e) => setNewPost(e.target.value)}
                                placeholder="📢 Share your community announcement..."
                                className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                            />
                            <button
                                type="submit"
                                disabled={submitting || !newPost.trim()}
                                className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
                            >
                                {submitting ? 'Posting...' : 'Post'}
                            </button>
                        </form>
                        {isCreator && (
                            <p className="text-xs text-gray-400 mt-2">👑 As the creator, your posts are highlighted as announcements</p>
                        )}
                    </div>

                    {/* Posts List */}
                    {posts.length === 0 ? (
                        <div className="text-center py-12 bg-white rounded-xl shadow-md">
                            <div className="text-4xl mb-4">📝</div>
                            <p className="text-gray-500">No posts yet</p>
                            <p className="text-sm text-gray-400">
                                {isCreator 
                                    ? 'Be the first to share an announcement in your community!' 
                                    : 'Be the first to share in this community!'}
                            </p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {posts.map((post) => {
                                const isPostCreator = post.user_id === community.creator_id
                                return (
                                    <div key={post.id} className={`bg-white rounded-xl shadow-md p-4 ${isPostCreator ? 'border-2 border-yellow-400' : ''}`}>
                                        <div className="flex items-center gap-3 mb-3">
                                            <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                                                {post.profiles?.username?.[0]?.toUpperCase() || 'U'}
                                            </div>
                                            <div>
                                                <div className="font-semibold flex items-center gap-2">
                                                    {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                                    {isPostCreator && (
                                                        <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full">👑 Admin</span>
                                                    )}
                                                </div>
                                                <div className="text-xs text-gray-400">@{post.profiles?.username} • {new Date(post.created_at).toLocaleDateString()}</div>
                                            </div>
                                        </div>
                                        <p className="text-gray-800 mb-3">{post.text}</p>
                                        {post.prediction_data && (
                                            <div className="bg-gray-50 rounded-lg p-3 mb-3">
                                                <div className="flex items-center justify-between text-sm">
                                                    <span>📊 {post.prediction_data.result || 'Draw'}</span>
                                                    <span>🟨{post.prediction_data.yellowCards || 0} 🟥{post.prediction_data.redCards || 0}</span>
                                                    <span>🏁{post.prediction_data.corners || 0}</span>
                                                </div>
                                            </div>
                                        )}
                                        <button 
                                            onClick={() => handleLike(post.id)}
                                            className="flex items-center gap-1 text-sm text-gray-400 hover:text-red-500 transition"
                                        >
                                            ❤️ {post.likes_count || 0}
                                        </button>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </>
            ) : (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">🔒</div>
                    <p className="text-gray-500">This community is private</p>
                    <p className="text-sm text-gray-400">Only the creator can post in this community</p>
                    <button 
                        onClick={handleJoin}
                        className="mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition"
                    >
                        Join Now
                    </button>
                </div>
            )}

            {/* Payment Modal */}
            {showPaymentModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <h2 className="text-xl font-bold text-gray-800 mb-4">💳 Join {community.name}</h2>
                        
                        <div className="bg-gray-50 rounded-lg p-4 mb-4">
                            <div className="flex justify-between items-center">
                                <span className="text-gray-600">Monthly subscription</span>
                                <span className="font-bold text-xl">R50</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500 mt-2 border-t pt-2">
                                <span>👤 Creator earns</span>
                                <span>R25</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500">
                                <span>🏢 Platform fee</span>
                                <span>R25</span>
                            </div>
                            <p className="text-xs text-gray-400 mt-2">Cancel anytime. You'll be charged R50/month.</p>
                        </div>

                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowPaymentModal(false)}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handlePayment}
                                disabled={submitting}
                                className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
                            >
                                {submitting ? 'Processing...' : 'Pay R50'}
                            </button>
                        </div>

                        <p className="text-xs text-gray-400 text-center mt-4">
                            For demo purposes, no actual payment will be taken.
                        </p>
                    </div>
                </div>
            )}
        </div>
    )
}
